import{_ as e,a0 as x,w as a,s as r,I as n,x as o,a1 as i,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Fotoxx：用於管理和編輯大型照片集合的開源應用 | LCTT x X-CMD","titleTemplate":false,"description":"Fotoxx：用於管理和編輯大型照片集合的開源應用 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fotoxx：用於管理和編輯大型照片集合的開源應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fotoxx：用於管理和編輯大型照片集合的開源應用 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection","title":"Fotoxx：用於管理和編輯大型照片集合的開源應用","tag":"202107","desc":""},"relativePath":"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection.md","filePath":"[post].md"}'),u={name:"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection.md"};function f(d,t,g,m,T,C){const s=x("Link");return a(),r("div",null,[t[24]||(t[24]=n("h1",{id:"fotoxx-用於管理和編輯大型照片集合的開源應用",tabindex:"-1"},[o("Fotoxx：用於管理和編輯大型照片集合的開源應用 "),n("a",{class:"header-anchor",href:"#fotoxx-用於管理和編輯大型照片集合的開源應用","aria-label":"Permalink to “Fotoxx：用於管理和編輯大型照片集合的開源應用”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/07/131024ej2kzv824zqb4zz8.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=o("説到 ",-1)),i(s,{href:"https://itsfoss.com/linux-photo-management-software/"},{default:p(()=>[...t[0]||(t[0]=[o("Linux 中的照片管理軟件",-1)])]),_:1}),t[2]||(t[2]=o("，Shotwell 可能是其中最有名的。難怪它在許多發行版中都預裝了。",-1))]),t[26]||(t[26]=l('<p>但是，如果你正在尋找一個類似 Shotwell 而速度更快的應用，Fotoxx 可能是一個不錯的選擇。</p><p>它可能沒有一個現代的用户界面，但它在處理大量照片集合時速度很快。這一點很重要，因為索引和顯示成千上萬張照片的縮略圖可能需要相當多的時間和計算資源。</p><h3 id="用-fotoxx-在-linux-中管理照片並編輯它們" tabindex="-1">用 Fotoxx 在 Linux 中管理照片並編輯它們 <a class="header-anchor" href="#用-fotoxx-在-linux-中管理照片並編輯它們" aria-label="Permalink to “用 Fotoxx 在 Linux 中管理照片並編輯它們”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-interface.jpg?resize=800%2C561&amp;ssl=1" alt="Fotoxx interface"></p><p>正如你在上面的截圖中看到的，它沒有漂亮的界面。看起來更像是一個 2010 年左右的應用。它在視覺上的不足，在功能和性能上得到了彌補。</p><p>你可以導入大量的照片，包括 RAW 圖像。這些圖片保持原樣。它們不會被複制或移動。它們只是在應用中被索引。</p><p>你可以編輯圖像元數據，如標籤、地理標籤、日期、評級、標題等。你可以根據這些元數據來搜索圖片。</p><p>它還有一個地圖功能，可以分組並顯示屬於某個地點的圖片（基於圖片上的地理標籤數據）。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-geotag-map-view.jpg?resize=800%2C466&amp;ssl=1" alt="Map view"></p><p>由於它專注於管理大型照片集合，有幾個批處理功能，可以重命名、調整大小、複製/移動、轉換圖像格式和編輯元數據。</p><p>你可以選擇圖片來創建相冊和幻燈片，所有這些都是在去重圖片的情況下進行的。照片可以組合成 360 度的全景圖。</p><p>Fotoxx 還有幾個編輯功能，可以用來修飾圖片，添加效果（如素描、繪畫）、修剪、旋轉等。</p><p>還有一些選項可以去除舊的、掃描照片打印件上的紅眼和塵斑。</p>',13)),n("p",null,[t[4]||(t[4]=o("我可以繼續列舉功能清單，但這太長了。它的網站描述了它的",-1)),i(s,{href:"https://kornelix.net/fotoxx/fotoxx.html"},{default:p(()=>[...t[3]||(t[3]=[o("全部功能",-1)])]),_:1}),t[5]||(t[5]=o("，你應該去看看。",-1))]),t[27]||(t[27]=l('<h3 id="在-linux-上安裝-fotoxx" tabindex="-1">在 Linux 上安裝 Fotoxx <a class="header-anchor" href="#在-linux-上安裝-fotoxx" aria-label="Permalink to “在 Linux 上安裝 Fotoxx”">​</a></h3><p>請記住，<strong>Fotoxx 的開發者建議使用一台強大的計算機</strong>，有 4 個以上的 CPU 核心，16GB 以上的內存，以便正常運行。較小的計算機可能會很慢，或可能無法編輯大型圖像。</p><p>Fotoxx 在大多數 Linux 發行版中都有，如 Debian、Ubuntu、Fedora 和 Arch Linux。只需使用你的發行版的包管理器或軟件中心來搜索 Fotoxx 並安裝它。</p><p>在基於 Ubuntu 和 Debian 的發行版上，你可以使用 apt 命令來安裝它，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fotoxx</span></span></code></pre></div><p>當你第一次運行它時，它會要求搜索主目錄中的圖像。你可以繼續使用它，或者將搜索位置限制在選定的文件夾。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-indexing.png?resize=800%2C617&amp;ssl=1" alt=""></p><p>我注意到，儘管在一分鐘左右的時間內索引了 4700 多張，但它並沒有立即開始顯示圖片。我不得不<strong>點擊 Gallery-&gt;All Folders，然後選擇文件夾，然後它就顯示了圖片</strong>。所以，這一點要記住。</p>',8)),n("p",null,[t[7]||(t[7]=o("Fotoxx 是一個功能廣泛的工具，你需要一些時間來適應它並探索它的",-1)),i(s,{href:"https://kornelix.net/fotoxx/fotoxx.html"},{default:p(()=>[...t[6]||(t[6]=[o("所有功能",-1)])]),_:1}),t[8]||(t[8]=o("。它的網站列出了幾個例子，你應該看看。",-1))]),t[28]||(t[28]=n("p",null,"正如我前面所説，它不是最漂亮的應用，但它大量的功能列表可以完成任務。如果你是一個攝影師或有大量的圖片收藏，你可以試試 Fotoxx，看看它是否符合你的需要。當你試過後，請在評論區分享你的經驗。",-1)),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(s,{href:"https://itsfoss.com/fotoxx/"},{default:p(()=>[...t[9]||(t[9]=[o("https://itsfoss.com/fotoxx/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("作者：",-1)),i(s,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...t[11]||(t[11]=[o("Abhishek Prakash",-1)])]),_:1}),t[16]||(t[16]=o(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[12]||(t[12]=[o("lujun9972",-1)])]),_:1}),t[17]||(t[17]=o(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:p(()=>[...t[13]||(t[13]=[o("geekpi",-1)])]),_:1}),t[18]||(t[18]=o(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...t[20]||(t[20]=[o("Linux中國",-1)])]),_:1}),t[23]||(t[23]=o(" 榮譽推出",-1))])])}const L=e(u,[["render",f]]);export{k as __pageData,L as default};
